-- The sheet as it stood after each change: every stored row of the sheet, taken once the change is
-- made, with the sheet's today then (made_on; none for the empty sheet first loaded, which counts
-- from the beginning of time). An as-of view shows the last one made on or before its date.
CREATE TABLE sheet_snapshot (
    seq      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    made_on  DATE,
    data     BLOB         NOT NULL
);
CREATE INDEX sheet_snapshot_sheet ON sheet_snapshot (sheet_id, seq);
-- A person's snapshot lines: one per SNAPSHOT written for them when the sheet's today moved, the day
-- being left and their due-total then (null: n/a). pos orders them, oldest first.
CREATE TABLE person_snapshot (
    person_id BIGINT        NOT NULL REFERENCES person (id),
    pos       INT           NOT NULL,
    left_on   DATE          NOT NULL,
    due_total DECIMAL(19, 2)
);
CREATE INDEX person_snapshot_person ON person_snapshot (person_id);
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.math.BigDecimal;
import java.time.LocalDate;

/** One of a person's snapshot lines: the day being left when the sheet's today moved, and their due-total then. */
@Embeddable
public class PersonSnapshot {

    /** The order the lines were written in, oldest first. */
    @Column(name = "pos", nullable = false)
    private int pos;

    @Column(name = "left_on", nullable = false)
    private LocalDate day;

    /** The due-total on the day; null for n/a. */
    @Column(name = "due_total")
    private BigDecimal dueTotal;

    protected PersonSnapshot() {
    }

    public LocalDate getDay() {
        return day;
    }

    public BigDecimal getDueTotal() {
        return dueTotal;
    }
}
